def add(title,typ='columns',lead='',items=None,takeaway='',pages='',notes='',**kw):
    s=dict(title=title,type=typ,lead=lead,source='教材第四章 '+pages if pages else '教学设计 / 新校区咖啡店模拟',notes=notes)
    if items is not None:s['items']=items
    if takeaway:s['takeaway']=takeaway
    s.update(kw);slides.append(s)
def table(title,headers,rows,**kw):add(title,'table',headers=headers,rows=rows,**kw)
add('不确定型决策分析','cover',notes='本章2学时，共90分钟。主讲24页，附录用于课前计算和课后核验。先让学生说明采用什么准则，再揭示结果；避免把选择准则当成算出想要结论后的辩解。')
add('新校区开店，连概率也拿不准',items=[['第三章的前提','可以估计状态概率\n按概率比较期望或期望效用\n信息能够更新概率'],['第四章的新情境','校区刚启用，缺少可比记录\n可以列需求状态与净价值\n尚不能给出可信概率']],takeaway='换了情境与信息条件；不能为了换算法，就随意删除已有可信概率。',pages='§1，p.89—90',notes='贯穿项目保持校园商业背景，但改为新校区、新一轮决策。先请学生指出还缺什么证据。如果后来获得可信概率，应回到第三章的风险型框架。')
add('能计算损益，不代表能预测频率',pages='§1，p.89—90',items=[['四个基本条件','明确目标\n至少两个自然状态与两个行动\n各行动在各状态下的结果可描述'],['本章要做的判断','状态互斥、穷尽且含义清楚\n先检查资金和产能等约束\n再声明比较方案的准则']],takeaway='准则给出条件性的选择依据，不保证选中的方案在真实状态下最好。',notes='教材表4-2为[100,50]和[30,150]，没有逐状态支配关系，因而需要评价规则。不要把“不能确定概率”误写成“所有事情都无法量化”。')
