table('五种准则，五个不同的问题',['准则','它问什么','看哪里'],[['乐观','最好能做到什么？','每行最好结果'],['悲观','最坏能保障什么？','每行最坏结果'],['折中','最好与最坏各重视多少？','两端及乐观系数'],['后悔值','事后最多错过多少？','每列基准与差额'],['等概率','若各状态等权，平均怎样？','全部结果的算术平均']],pages='§1—6，p.90—106',notes='五种准则不保证给出五个不同答案，也不是投票多数决定最终方案。先辨收益/成本方向；本表先以收益表讲解。')
add('乐观：在最好结果中取最好','equations',pages='§2，p.90—93',items=[['先逐行找最大收益','快闪 6；标准 12；旗舰 20；不投资 0','再取最大：20 → 旗舰店'],['它保留了什么、忽略了什么？','保留每行的收益上限','旗舰店低需求时 −10，并没有因乐观而消失']],takeaway='乐观是评价态度，不是“高需求一定会发生”的预测。',notes='教材又称大中取大。强调上行机会的同时仍应先审查可承受损失与可行性。教材所列适用背景是启发性讨论，不是企业规模决定算法的机械规则。')
add('悲观：在最坏结果中取最好','equations',pages='§3，p.93—96',items=[['先逐行找最小收益','快闪 2；标准 −2；旗舰 −10；不投资 0','再取最大：2 → 快闪店'],['先守住下限','在列出的状态范围内，快闪至少获得 2 万元','这不是保证现实中不存在未建模的更坏情况']],takeaway='悲观准则最大化最坏保障；不是在所有格子里挑最小收益。',notes='教材又称小中取大。每行最坏状态未必是同一列；不要把它解释为同一个客观状态以概率1发生。')
add('把每个方案的两端画出来','interval',rows=['快闪店','标准店','旗舰店','不投资'],matrix=[[6,5,2],[12,7,-2],[20,6,-10],[0,0,0]],takeaway='旗舰店上限最高，快闪店下限最好；中间状态在这幅图里不可见。',notes='横线只表示损益最小值至最大值的范围，不是置信区间，也不说明中间金额都能发生。两端标出明确数值，避免把线长当作概率。')
add('折中：让乐观程度可见','equations',pages='§4，p.96—98',items=[['α 是乐观系数，0≤α≤1','H(a)=α×最好收益+(1−α)×最坏收益','α=0 为悲观，α=1 为乐观'],['默认 α=0.6','快闪 4.4；标准 6.4；旗舰 8；不投资 0','折中准则选旗舰店']],takeaway='α乘的是最好结果；若别的材料用“悲观系数”，必须先核对定义。',notes='本章所有公式和网页都统一乐观系数语义。成本型最好是最低成本，因此α仍乘最好，却改乘最小值。')
add('拖动 α，观察推荐在哪切换','chart',series=[{'name':'快闪店','points':[[a/100,2+4*a/100]for a in range(101)]},{'name':'标准店','points':[[a/100,-2+14*a/100]for a in range(101)]},{'name':'旗舰店','points':[[a/100,-10+30*a/100]for a in range(101)]}],xlabel='乐观系数 α',ylabel='折中得分 / 万元',items=[['α=0.4','快闪与标准并列最优'],['α=0.5','标准与旗舰并列最优']],takeaway='α<0.4 快闪；0.4<α<0.5 标准；α>0.5 旗舰。',notes='所有行动都必须参与计算；不投资恒为0，此基准例从未最优，图中省略这条线。快闪与旗舰也在6/13相交，但标准在其上方，这不是最优切换点。网页保留全部行动。')
add('α=0.6，不等于高需求概率60%',pages='§4，p.98—101',items=[['α 是评价权重','只连接每个行动的最好与最坏\n不同方案的最好可能在不同状态\n中间状态没有参与折中得分'],['概率是状态描述','第三章的权重对应同一组状态\n需要数据或明确的概率判断\n不能直接用α代替所有状态概率']],takeaway='相同最好与最坏的两个方案，在任意α下折中得分都相同。',notes='教材用标准化[1,0]与确定x的无差异关系测定α；这依赖所声明的折中模型，不能当作一次提问就精确测出了客观概率或完整效用函数。')
add('后悔值：按列建立事后基准','flow',pages='§5，p.101—103',steps=['逐列找最好','计算差额','每行找最大','选最小者'],details=['每个状态分别比较','基准收益−本方案收益','最坏会错过多少','最小化最大后悔'],takeaway='先按状态做列运算，再按方案做行运算；不能按行的最大值相减。',notes='后悔值是机会损失，不是心理情绪测量，也不是实际财务亏损。第三章EOL按概率加权；本章无概率，使用最大后悔。')
add('原表变成后悔值表','heatmap',lead='逐列最好收益为 20、7、2 万元；下面全部是非负机会损失。',matrix=[[14,2,0],[8,0,4],[0,1,12],[20,7,2]],rows=['快闪店','标准店','旗舰店','不投资'],headers=['高需求','中需求','低需求'],regret=True,takeaway='每行最大后悔：14、8、12、20；取最小的 8 → 标准店。',notes='请学生手算标准店低需求：2−(−2)=4。快闪没有负收益，但高需求时错过14万元；没有财务亏损并不等于没有后悔值。')
add('成本型：方向必须一起改变','equations',pages='§2—5，p.91、94、103',items=[['成本越低越好','乐观：各行最小成本，再取最小','悲观：各行最大成本，再取最小'],['统一使用非负后悔值','每列基准 = 该状态最低成本','成本后悔 = 本方案成本−列基准；仍选最小的行最大值']],takeaway='本课成本后悔保持非负；不要套“列最大−原值”的收益公式。',notes='教材p.103给出另一套等价的负差额写法：列最小−原成本，取每行最小再取最大。本课采用非负机会损失，更利于统一展示；两种写法不能混用取优方向。')
add('等概率：等权是一项额外假设','equations',pages='§6，p.104—106',items=[['三状态各赋 1/3','快闪 13/3≈4.333；标准 17/3≈5.667','旗舰 16/3≈5.333；不投资 0 → 标准店'],['它利用了全部格子','收益表选平均值最大；成本表选平均值最小','不知道概率，并不能推出真实概率相等']],takeaway='改变状态划分，会改变“每列等权”的含义。',notes='教材又称Laplace准则。保留主准则的全部并列最优。教材p.105另提出同均值时以均值减最坏收益作辅助比较；如采用要另行声明，不悄悄用于打破并列。')
table('五种准则对同一案例的回答',['准则','最优方案','它优先考虑的证据'],[['乐观','旗舰店','最好结果20'],['悲观','快闪店','最坏保障2'],['折中，α=0.6','旗舰店','两端加权得分8'],['最小最大后悔','标准店','最大机会损失8'],['等概率','标准店','等权平均17/3']],takeaway='不同答案来自不同评价依据；最终建议还要说明约束与责任。',notes='不是三票对两票就决定开标准店。也不能把最好上限20、后悔值8和均值5.667当作同一类评分直接横比。')
add('C4-E1：先声明准则，再改参数','activity',items=[['先预测','选择你能辩护的一项准则，写出它关心的结果。'],['再操作','修改矩阵；拖动α到0、0.4、0.5、1；查看并列与切换。'],['后解释','一次只改变一个输入，说明哪个中间量导致推荐改变。']],takeaway='记录准则、数据、α与结果；不能只交“网页推荐了谁”。',notes='比较台有全部五种准则的并列结果、所选准则逐步计算、折中曲线。输入错误时清除旧结果，避免学生将无效输入与旧结论配对。')
add('C4-E2：用一格数据查出方向错误','activity',items=[['按列找基准','在网页选择一个状态，先猜该列最优值。'],['逐步揭示','从原表到列基准、非负差额，再到行最大后悔。'],['切换成本案例','选择教材习题2；手算 A 在状态2的后悔：40−24=16。']],takeaway='成本表逐列基准21、24、20；最大后悔16、20、17，选A。',notes='网页语义切换不自动改原数值；另有“取负并切换”保持偏好等价的按钮，展示收益V和成本−V的数学对应。真实成本通常非负，但代数转换允许负数。')
add('三个反例，提醒我们保留判断',pages='§4—6，p.100—106',items=[['极值不够','最好和最坏一样\n中间结果可以很不同\n折中准则仍然并列'],['基准会变化','新增一个没被选中的方案\n也可能改变后悔基准\n状态细分会改变等权平均']],takeaway='这些是准则的结构特点；报告应展示敏感性与信息限制。',notes='网页提供三个成对预设：相同极值反例；[10,0]/[4,4]与把低状态复制一次；加入[0,10]使最大后悔推荐从A改B。无概率时不能把状态个数直接当发生频率。')
