add('M4：给 M3 加上“概率不可靠”分支','project',items=[['信息边界','说明哪些概率依据不足；保留能验证的事实和可行约束。'],['比较证据','同一矩阵列五准则结果；给α切换区间与后悔表。'],['条件建议','辩护主准则，说明最坏损失与待补证据；提出转回风险型分析的条件。']],takeaway='在原项目档案追加1页＋计算附件；不重新做一份独立大项目。',notes='如果本组M3已有可信概率，不强行宣称概率未知。可以另选一个新市场或新技术情境，解释为什么旧概率不能直接迁移。所有模拟数据标明。')
add('翻转课堂：五组顾问，同一张表','activity',items=[['课前15分钟','读五准则计算卡，手算一个收益表和一个成本后悔值。'],['课内准则辩护','每组先让听众预测，3分钟解释推荐和风险，2分钟接受改参质询。'],['个人退出题','独立说明α含义、成本方向及等概率假设，不用小组答案替代。']],takeaway='评分：计算35%、方向与假设25%、准则辩护25%、表达协作15%。',notes='90分钟安排：导入10、准则与例题25、比较台15、后悔放大镜15、辩论15、退出题10。班级较大时分区同时讲解，教师抽查，不要求所有组排队展示。')
add('离开教室前，回答这三问','activity',items=[['算与辨','成本行[3,8]：悲观准则看3还是8？'],['解释系数','α=0.7能否直接写成“市场好概率70%”？'],['判断并列','等权平均相同，是否可以由程序随便选一个方案？']],takeaway='参考：看8后再跨方案取小；不能；保留并列，若加辅助准则要明说。',notes='网页另有六题自动反馈。课堂退出题3分钟独答、3分钟互查、4分钟教师反馈。重点记录方向错误，不只记总分。')
add('本章带走的是一套可辩护的比较',items=[['先把模型说明白','行动与状态不混淆\n收益或成本方向一致\n概率未知不等于等概率'],['再把判断说明白','声明准则与α的含义\n展示阈值、并列与后悔值\n记录约束和待补证据']],takeaway='下一章：当利润、服务、环境等多个目标同时重要，怎样综合评价？',pages='本章小结，p.108',notes='回到开场投票，让学生补写推荐条件。没有一种准则在所有未知概率问题中自动正确；也不意味着可以无视证据和约束任意挑选。')
